function trySend() {
  if (!isAskable(draft) || waiting || activeRequest.current) return;
  const question = questionWithContext(
    draft.trim(),
    exploration.contextView,
    exploration.contextPath,
  );
  const decision = decideSubmit(providers, selectedProvider, unlockedProvidersRef.current);
  if (decision.kind === 'prompt-password') {
    pendingQuestionRef.current = question;
    setPasswordDraft('');
    setPasswordError(null);
    setPasswordModalOpen(true);
    return;
  }
  setDraft('');
  const password =
    selectedProvider !== null
      ? (providerPasswordsRef.current.get(selectedProvider) ?? null)
      : null;
  void sendTurn(question, selectedProvider, password);
}

// The password modal's own submit — the one place a `provider`+`password` pair is actually
// proven against the server, since there is no separate "verify" endpoint: this *is* the real
// `POST /api/chat` call for the question that was held back. A non-200 (401 for a wrong
// password, in practice) shows the server's own refusal text in the modal and changes nothing
// else — the question stays pending in `pendingQuestionRef`, and the reader may retry or cancel.
// A 200 unlocks the provider for the rest of this conversation and turns the already-fetched
// response into a normal resolved turn, exactly like `sendTurn` would have, without a second
// network call.
async function submitPasswordModal(event: FormEvent) {
  event.preventDefault();
  const question = pendingQuestionRef.current;
  const provider = selectedProvider;
  if (question === null || provider === null || passwordChecking || activeRequest.current) return;
  const generation = conversationGeneration.current;
  setPasswordChecking(true);
  // One request owns both password validation and visible progress; a refusal reopens the modal.
  setPasswordModalOpen(false);
  const response = await sendTurn(question, provider, passwordDraft);
  if (generation !== conversationGeneration.current || !response) return;
  setPasswordChecking(false);
  if (response.status === 401 || response.status === 403) {
    setTurns((current) => current.filter((turn) => turn.id !== nextTurnId.current - 1));
    setPasswordModalOpen(true);
    setPasswordError(turnResultFrom(response).error);
    return;
  }
  if (response.status === 200) {
    unlockedProvidersRef.current.add(provider);
    providerPasswordsRef.current.set(provider, passwordDraft);
  }
  pendingQuestionRef.current = null;
  setPasswordDraft('');
  setPasswordError(null);
  setDraft('');
}

function cancelPasswordModal() {
  pendingQuestionRef.current = null;
  setPasswordModalOpen(false);
  setPasswordDraft('');
  setPasswordError(null);
}

async function sendTurn(
  question: string,
  provider: string | null = null,
  password: string | null = null,
) {
  const generation = conversationGeneration.current;
  const id = nextTurnId.current++;
  const controller = new AbortController();
  activeRequest.current = controller;
  let live: LiveExploration | undefined;
  setTurns((current) => [...current, pendingTurn(id, question)]);
  const response = await postChat(
    question,
    sessionIdRef.current,
    provider,
    password,
    provider === null && localModelsAvailable ? localModel : undefined,
    undefined,
    { conversationId: restoredSessionRef.current },
    {
      signal: controller.signal,
      clientRequestId: crypto.randomUUID(),
      isCurrent: () =>
        generation === conversationGeneration.current && activeRequest.current === controller,
      onEvent: (event) => {
        live = receiveLive(live, event);
        if (!live) return;
        const received = live;
        setTurns((current) =>
          current.map((turn) => (turn.id === id ? { ...turn, live: received } : turn)),
        );
        dispatch({ type: 'progress', exploration: received });
      },
    },
  );
  if (generation !== conversationGeneration.current) return response;
  activeRequest.current = null;
  const completed = readExploration(response.body).exploration;
  if (completed) dispatch({ type: 'complete', exploration: completed });
  else if (live) {
    const interrupted: LiveExploration = { ...live, status: 'interrupted' };
    dispatch({ type: 'progress', exploration: interrupted });
    setTurns((current) =>
      current.map((turn) => (turn.id === id ? { ...turn, live: interrupted } : turn)),
    );
  }
  applyRateLimit(response);
  const sessionId = readSessionId(response);
  if (sessionId !== null) {
    sessionIdRef.current = sessionId;
    setSessionIdReady(true);
  }
  setTurns((current) => resolveTurn(current, id, response));
  return response;
}

function startNewChat() {
  activeRequest.current?.abort();
  activeRequest.current = null;
  conversationGeneration.current++;
  dispatch({ type: 'reset' });
  setPasswordChecking(false);
  setTurns([]);
  setDraft('');
  nextTurnId.current = 0;
  sessionIdRef.current = null;
  restoredSessionRef.current = undefined;
  setSessionNotice('');
  setSessionList([]);
  setSessionPassword('');
  setSessionIdReady(false);
  setReportPanelOpen(false);
  setReportMarkdown(null);
  setReportSelection([]);
  setReportError(null);
  setReportGenerating(false);
  // sap-harness#303/#338: a fresh conversation starts with no unlocked provider and no
  // remembered password either — a new conversation resuming a paid provider's *old* unlock
  // would be a request the reader never re-authorised for this session. The provider
  // *selection* itself and the fetched `providers` list survive, same as a radio group survives
  // a form reset elsewhere on this page. sap-harness#337: the rate-limit line is per-request
  // state with nothing left to show once the conversation it was measuring is gone.
  unlockedProvidersRef.current.clear();
  providerPasswordsRef.current.clear();
  cancelPasswordModal();
  setRateLimit(null);
  resetSplit();
}

export function decideSubmit(
  providers: readonly ProviderInfo[],
  selectedProvider: string | null,
  unlockedProviders: ReadonlySet<string>,
): SubmitDecision {
  if (selectedProvider === null) return { kind: 'send' };
  const provider = providers.find((candidate) => candidate.name === selectedProvider);
  if (provider === undefined || !provider.requiresPassword) return { kind: 'send' };
  if (unlockedProviders.has(selectedProvider)) return { kind: 'send' };
  return { kind: 'prompt-password' };
}

export async function postChat(
  question: string,
  sessionId: string | null,
  provider?: string | null,
  password?: string | null,
  localModel?: 'claude' | 'codex',
  rowAction?: RowAction,
  history?: { conversationId?: string; rowOwner?: { turnId: string; slotId: string } },
  stream?: ChatStreamOptions,
): Promise<ChatResponse> {
  const body: Record<string, unknown> = { question };
  if (stream) body.clientRequestId = stream.clientRequestId;
  if (history?.conversationId) body.conversationId = history.conversationId;
  if (history?.rowOwner) body.rowOwner = history.rowOwner;
  if (sessionId !== null) body.sessionId = sessionId;
  if (provider !== undefined && provider !== null) body.provider = provider;
  if (password !== undefined && password !== null) body.password = password;
  if (localModel !== undefined) body.localModel = localModel;
  if (rowAction) {
    if ('confirmationId' in rowAction) body.rowConfirmation = rowAction.confirmationId;
    else body.rowRead = { tool: rowAction.tool, input: rowAction.input };
  }
  const controller = new AbortController();
  const abort = () => controller.abort();
  stream?.signal.addEventListener('abort', abort, { once: true });
  if (stream?.signal.aborted) abort();
  if (stream && typeof window !== 'undefined')
    window.addEventListener('pagehide', abort, { once: true });
  try {
    const response = await fetch(CHAT_PATH, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        ...(stream ? { Accept: 'text/event-stream', 'X-Graph-Stream-Version': '1' } : {}),
      },
      body: JSON.stringify(body),
      ...(stream ? { signal: controller.signal } : {}),
    });
    // HTTP succeeded when SSE opened; only validated terminal events decide the turn outcome.
    let status = response.status;
    const responseBody: unknown =
      stream && response.ok
        ? await readChatStream(response, {
            ...stream,
            signal: controller.signal,
            onEvent(event) {
              if (event.kind === 'turn-error') status = 502;
              else if (event.kind === 'turn-cancelled') status = 499;
              stream.onEvent(event);
            },
          })
        : await response.json().catch(() => null);
    return {
      status,
      body: responseBody,
      rateLimit: rateLimitFromHeaders((name) => response.headers.get(name)),
    };
  } catch (error) {
    if (!stream) throw error;
    return {
      status: controller.signal.aborted || !stream.isCurrent() ? 499 : 502,
      body: {
        error: controller.signal.aborted
          ? '분석을 중지했습니다.'
          : '분석 연결이 중단되었습니다. 다시 시도하세요.',
        streamState:
          controller.signal.aborted || !stream.isCurrent() ? 'cancelled' : 'disconnected',
      },
    };
  } finally {
    controller.abort();
    stream?.signal.removeEventListener('abort', abort);
    if (stream && typeof window !== 'undefined') window.removeEventListener('pagehide', abort);
  }
}

export function isAskable(draft: string): boolean {
  return draft.trim().length > 0;
}
